// hr — Hrvatski (croata).
//
// A chave é o TEXTO EM PORTUGUÊS, exatamente como aparece no código. O que faltar aqui aparece em
// português, e não como tela vazia.
//
// NÃO É O SÉRVIO. As duas se entendem, e o sr.ts está logo ao lado — mas o croata se escreve só em
// latino, é IJEKAVIANO (vrijeme, mlijeko, lijepo) e tem vocabulário próprio que um croata nota na hora:
// računalo (não kompjuter), datoteka (não fajl), preglednik (não pregledač), tjedan (não nedelja),
// tisuća (não hiljada), zrakoplov (não avion). Nada veio do sr.ts.
//
// TOM: **ti**, e não *Vi* — a escolha dos outros eslavos do Syden. O Vi é o de banco e de repartição.
//
// GÊNERO: ESTÁ NO PASSADO E NO ADJETIVO, como no sérvio, no polonês e no tcheco: zaboravio (homem) /
// zaboravila (mulher), siguran / sigurna. A saída é a mesma: presente, futuro, impessoal (obrisano,
// poslano) e advérbio ("Stvarno obrisati…?"). Os nomes de cargo (Administrator, Vlasnik, Član) ficam no
// masculino genérico, como em toda interface croata.
//
// PLURAL: três formas (1 poruka, 2–4 poruke, 5+ poruka). O t() não escolhe forma: rótulo e número,
// "Poruke: {n}".
//
// DECLINAÇÃO: o croata declina nome próprio, então {nome} nunca vem colado à preposição — vem depois de
// um substantivo que leva o caso ("u zajednici {comunidade}") ou depois de dois-pontos.
//
// NÚMEROS: `Intl.NumberFormat('hr')` devolve `1.234.567` — latinos, com ponto de milhar.
//
// O DETECTOR DO TESTE DE IDIOMAS: latino com č, ć, đ, š, ž e nenhum acento do português — vai o das
// chaves, que é a regra de toda língua latina.
//
// VOCABULÁRIO, decidido uma vez: comunidade = zajednica, canal = kanal, sala de voz = glasovna soba,
// chamada = poziv, conversa = razgovor, mensagem = poruka, senha = lozinka, lixeira = koš, tópico =
// nit, conta = račun, administrador = administrator, dono = vlasnik, cargo = uloga, convite =
// pozivnica, perfil = profil, transmissão = prijenos, tela = zaslon, membro = član, pacote = paket,
// enquete = anketa, denúncia = prijava, vila = selo, guarda-roupa = garderoba, cutucada = bockanje,
// recado (da tela de boas-vindas e do aviso) = obavijest.
//
// SOM E VOZ SÃO DUAS PALAVRAS: glas é a voz, zvuk é o som de soundboard e de aviso.
//
// SELO E INSÍGNIA SEPARADOS: selo = pečat (o da comunidade), insígnia = značka (a da pessoa).

