  'É a primeira coisa que alguém vê ao entrar na comunidade, uma vez só. Sem isto, a pessoa cai direto na lista de canais.':
    'To je prvo što netko vidi kad uđe u zajednicu, samo jednom. Bez toga se ide ravno na popis kanala.',
  'É assim que os outros veem você na lista e nas conversas.': 'Ovako te drugi vide na popisu i u razgovorima.',
  'é o que você está enviando': 'je ono što šalješ',
  'É o seu único jeito de entrar. Defina uma senha antes de desligar.': 'To ti je jedini način prijave. Postavi lozinku prije nego što prekineš vezu.',
