  'Quando uma mensagem junta estrelas ⭐ suficientes, o Syden a publica no canal de destaques. A estrela de quem escreveu não conta, e apagar a mensagem apaga o destaque.': 'Kad poruka skupi dovoljno zvjezdica ⭐, Syden je objavi u kanalu istaknutog. Zvjezdica autora poruke se ne broji, a brisanje poruke briše i istaknuto.',
