  'O Syden anuncia o prêmio no canal, e quem quiser participar reage com 🎉. Na hora marcada, ele sorteia entre quem reagiu e publica o resultado.': 'Syden objavi nagradu u kanalu, a tko želi sudjelovati reagira s 🎉. U zadano vrijeme izvlači među onima koji su reagirali i objavi rezultat.',
