  'Hoje é aniversário de {pessoa}! 🎉 Parabéns!': 'Danas je rođendan korisnika {pessoa}! 🎉 Sretan rođendan!',
  'Mês': 'Mjesec',
  'No dia do aniversário de quem informou a data, o Syden publica os parabéns no canal escolhido. Use {pessoa} no lugar do nome.': 'Na rođendan onoga tko je unio datum, Syden objavi čestitku u odabranom kanalu. Koristi {pessoa} umjesto imena.',
  'Só o dia e o mês, nunca o ano. As comunidades que avisam aniversários dão os parabéns no dia. É opcional, e dá para apagar quando quiser.': 'Samo dan i mjesec, nikad godina. Zajednice koje najavljuju rođendane čestitaju na taj dan. Neobavezno je i može se izbrisati kad god želiš.',
