  'Sai uma letra e cada um escreve uma palavra com ela em cada categoria. Quem completar primeiro aperta STOP, e a turma decide o que vale.': 'Izvuče se slovo i svatko u svaku kategoriju upiše riječ na to slovo. Tko prvi sve ispuni, pritisne STOP, a ekipa odlučuje što vrijedi.',
