  'Duas pessoas põem pedras no tabuleiro, uma de cada vez. Vence quem fizer cinco seguidas. A sala assiste.': 'Dvoje igrača naizmjence stavlja kamenčiće na ploču. Pobjeđuje tko složi pet u nizu. Soba gleda.',
