  'Lobisomem': 'Vukodlak',
  'À noite, escolha com os outros lobisomens quem atacar. De dia, não deixe ninguém desconfiar.': 'Noću s ostalim vukodlacima odaberi koga napasti. Danju ne daj nikome povoda za sumnju.',
  'Vidente': 'Proročište',
  'À noite, descubra se alguém é lobisomem. Conte de dia, se achar que vale o risco.': 'Noću otkrij je li netko vukodlak. Reci to danju, ako misliš da je vrijedno rizika.',
  'Anjo': 'Anđeo',
  'À noite, escolha alguém para proteger. Se os lobisomens atacarem essa pessoa, ela sobrevive.': 'Noću odaberi nekoga koga ćeš zaštititi. Ako vukodlaci napadnu tu osobu, ona preživi.',
  'Da vila': 'Iz sela',
  'À noite, durma. De dia, descubra quem são os lobisomens e vote para tirá-los do jogo.': 'Noću spavaj. Danju otkrij tko su vukodlaci i glasaj da ih izbacite iz igre.',
  'A vila venceu!': 'Selo je pobijedilo!',
  'Os lobisomens venceram!': 'Vukodlaci su pobijedili!',
  'Noite {n}. A vila dorme.': 'Noć {n}. Selo spava.',
  'Os lobisomens atacaram {nome} durante a noite.': 'Žrtva vukodlaka ove noći: {nome}.',
  'Ninguém morreu esta noite.': 'Ove noći nema žrtava.',
  'Dia {n}. Conversem e votem em quem vocês acham que é lobisomem.': 'Dan {n}. Razgovarajte i glasajte tko je po vama vukodlak.',
  'A vila tirou {nome} do jogo.': 'Selo je izbacilo iz igre: {nome}.',
  'Empate: ninguém sai hoje.': 'Neriješeno: danas nitko ne izlazi.',
  'Clique em quem os lobisomens vão atacar.': 'Klikni na osobu koju će vukodlaci napasti.',
  'Você já usou a sua visão esta noite.': 'Vizija za ovu noć već je iskorištena.',
  'Clique em alguém para descobrir se é lobisomem.': 'Klikni na nekoga da otkriješ je li vukodlak.',
  'Clique em quem você quer proteger esta noite.': 'Klikni na osobu koju želiš zaštititi ove noći.',
  'Durma. Os outros papéis estão agindo.': 'Spavaj. Ostale uloge djeluju.',
  'Você saiu do jogo. Agora só assiste — sem contar nada!': 'Više nisi u igri. Sad samo gledaš — bez odavanja!',
  'Clique em quem você quer tirar do jogo. O mais votado sai; empate, ninguém.': 'Klikni na osobu koju želiš izbaciti iz igre. Izlazi tko ima najviše glasova; kod neriješenog nitko.',
