  '{tipo} «{item}» ({onde}) saiu do Syden porque {quem} disse ter os direitos. Se você tinha autorização para publicar, responda aqui contando: a sua resposta vai ser levada em conta. Enquanto isso não ficar claro, fica fora. Os termos explicam como funciona, na seção 4: https://syden.chat/termos.html#direito-autoral': '{tipo} «{item}» ({onde}) više nije na Sydenu jer {quem} tvrdi da ima prava na to. Ako imaš dopuštenje za objavu, odgovori ovdje i objasni: tvoj će se odgovor uzeti u obzir. Dok se to ne razjasni, sadržaj ostaje uklonjen. Uvjeti objašnjavaju kako to funkcionira, u odjeljku 4: https://syden.chat/termos.html#direito-autoral',
