  'Abre os mini-games para jogar com a turma.': 'Otvara mini-igre za igru s ekipom.',
  'Cada prateleira guarda os canais da comunidade.': 'Svaka polica čuva kanale zajednice.',
  'Onde o coelho do recado espera quem chega.': 'Ovdje zec s porukom čeka one koji dolaze.',
  'Alta, para sentar no balcão e conversar.': 'Visoka, za sjedenje za šankom i čavrljanje.',
  'Uma máquina de música antiga, com luzes que acendem à noite.': 'Stari glazbeni automat, sa svjetlima koja noću svijetle.',
  'Com caixa de som, pronto para o karaokê.': 'Sa zvučnikom, spreman za karaoke.',
  'Redonda, para cartas, tabuleiro e conversa.': 'Okrugli, za karte, društvene igre i razgovor.',
  'De madeira, com o assento estofado.': 'Drvena, s tapeciranim sjedalom.',
  'Suco, refrigerante e água sempre gelados.': 'Sok, gazirano piće i voda, uvijek hladni.',
  'A cozinha da turma. O botão direito acende e apaga o fogão.': 'Kuhinja ekipe. Desni klik pali i gasi štednjak.',
  'Um pufe enorme, para afundar e ficar.': 'Golema vreća za sjedenje, za utonuti i ostati.',
  'Pendurado no gancho, esperando a próxima call.': 'Vise na kuki i čekaju sljedeći poziv.',
  'Fotos dos amigos presas num varal.': 'Fotografije prijatelja na konopcu.',
  'Recados e ideias presos com alfinete.': 'Poruke i ideje pričvršćene pribadačama.',
  'Livros, uma plantinha e um vaso.': 'Knjige, biljčica i vaza.',
  'Um pôr do sol sobre os campos.': 'Zalazak sunca nad poljima.',
  'Xícaras, potes e garrafas de suco.': 'Šalice, staklenke i boce soka.',
  'Potes de biscoito e pipoca para dividir.': 'Staklenke keksa i kokica za podijeliti.',
  'As taças das vitórias da turma.': 'Pehari pobjeda ekipe.',
  'Um coelho de neon que brilha no escuro.': 'Neonski zec koji svijetli u mraku.',
  'Um relógio de madeira para ninguém perder a hora.': 'Drveni sat da nitko ne izgubi pojam o vremenu.',
  'Para quem quiser puxar uma música.': 'Za svakoga tko želi zapjevati.',
  'Dá no banheiro. Bata antes de entrar.': 'Vodi u kupaonicu. Pokucaj prije ulaska.',
  'O cartaz do karaokê, em três versões: palco, neon e fogo.': 'Plakat za karaoke, u tri verzije: pozornica, neon i vatra.',
  'Dois coelhos, um café e a fofoca do dia.': 'Dva zeca, kava i trač dana.',
  'Café quentinho, ainda soltando fumaça.': 'Topla kava, još se puši.',
  'Suco de laranja com canudinho.': 'Sok od naranče sa slamkom.',
  'Uma lata gelada.': 'Hladna limenka.',
  'Uma suculenta pequena, que quase não pede água.': 'Mali sukulent kojem gotovo ne treba voda.',
  'Uma pilha de livros para ler depois.': 'Hrpa knjiga za kasnije čitanje.',
  'O console da turma, com o controle ao lado.': 'Konzola ekipe, s kontrolerom pokraj.',
  'Um balde de pipoca para ver a transmissão.': 'Kanta kokica za gledanje prijenosa.',
