  'Desvie das brasas. São só três corações!': 'Izbjegavaj žar. Srca su samo tri!',
  'Cabo de guerra': 'Potezanje užeta',
  'Aperte a seta que aparecer para puxar a corda. Errar trava!': 'Pritisni strelicu koja se pojavi da povučeš uže. Pogreška — i blokiraš!',
  'Canteiro que encolhe': 'Gredica koja se smanjuje',
  'Empurre os outros para fora do canteiro. A borda que pisca vai cair!': 'Guraj ostale s gredice. Rub koji treperi pasti će!',
  'Corrida de cavalinho': 'Utrka na konjiću',
  'Alterne ← e → no ritmo. Com pressa demais, o fôlego acaba.': 'Izmjenjuj ← i → u ritmu. Ako požuriš, ponestat će daha.',
  'Cartas do celeiro': 'Karte iz staje',
  'Na sua vez, vire uma carta ou guarde as cenouras. A raposa leva tudo!': 'Na svom potezu okreni kartu ili spremi mrkve. Lisica odnosi sve!',
  'Chuva de cenouras': 'Kiša mrkava',
  'Desça pegando as cenouras. Das pedras, fuja!': 'Spuštaj se i skupljaj mrkve. Od kamenja — bježi!',
  'De galho em galho': 'S grane na granu',
  'Solte o cipó quando ele estiver na faixa clara.': 'Pusti lijanu kad je u svijetloj traci.',
  'Colheita em dupla': 'Berba u paru',
  'Em dupla: quem está no galho solta os morangos maduros, e quem está embaixo apanha com a cesta.': 'U paru: tko je na grani, pušta zrele jagode, a tko je dolje, hvata ih košarom.',
  'Baile da toca': 'Bal u jazbini',
  'Guarde a ordem da dança. No fim, diga quem dançou na lâmpada marcada.': 'Zapamti redoslijed plesa. Na kraju reci tko je plesao na označenoj lampi.',
  'Chão que desmorona': 'Pod koji se ruši',
  'A tábua racha quando alguém para em cima. Continue andando e empurre os outros para a água!': 'Daska puca kad netko stane na nju. Nastavi hodati i guraj ostale u vodu!',
  'Arrume a despensa': 'Posloži smočnicu',
  'Guarde onde fica cada pote e ponha todos de volta no lugar.': 'Zapamti gdje stoji svaka staklenka i vrati ih sve na mjesto.',
  'Esconde-esconde na horta': 'Skrivača u povrtnjaku',
  'Esconda-se onde a lanterna não vai olhar. Quem tem a lanterna procura!': 'Sakrij se onamo kamo svjetiljka neće pogledati. Tko ima svjetiljku, traži!',
  'Três flechas': 'Tri strijele',
  'A flecha sobe reta e fura o que encontrar. Os balões pequenos valem mais.': 'Strijela ide ravno gore i probija sve na što naiđe. Mali baloni vrijede više.',
  'Bate quando der a flor': 'Lupi na cvijet',
  'Bata quando aparecer a flor igual à do quadrinho. Na figura errada, está fora.': 'Lupi kad se pojavi cvijet isti kao u okviru. Na pogrešnoj slici ispadaš.',
  'Foguete de cenoura': 'Raketa od mrkve',
  'Bombeie quando o anel acender. Fora do ritmo, o ar escapa.': 'Pumpaj kad se prsten upali. Izvan ritma — zrak izlazi.',
  'Pegue a galinha': 'Uhvati kokoš',
  'Encurrale a galinha. Cansada, ela fica lenta.': 'Satjeraj kokoš u kut. Umorna, postaje spora.',
  'Repolhos no gelo': 'Kupus na ledu',
  'Pegue as cenouras no gelo e fuja dos repolhos.': 'Skupljaj mrkve na ledu i bježi od kupusa.',
  'Abóboras ladeira abaixo': 'Bundeve nizbrdo',
  'Lá de cima rolam abóboras; quem sobe troca de faixa para fugir delas!': 'Odozgo se kotrljaju bundeve; tko se penje, mijenja traku da im pobjegne!',
  'Quem está atrás da turma?': 'Tko je iza gužve?',
  'Descubra quem está escondido. Uma chance só: quanto antes, mais vale.': 'Otkrij tko se skriva. Samo jedan pokušaj: što ranije, to više vrijedi.',
  'Arremesso do nabo': 'Bacanje repe',
  'Solte quando o nabo apontar para o campo. Girando mais rápido, vai mais longe.': 'Pusti kad repa pokazuje prema polju. Što se brže vrti, to dalje leti.',
  'Onda no açude': 'Val na bari',
  'Quem está no remo manda ondas; quem está na jangada pula na hora!': 'Tko je na veslu, šalje valove; tko je na splavi, skače na vrijeme!',
  'Pula o ponteiro': 'Preskoči kazaljku',
  'Pule quando o ponteiro passar. Ele fica cada vez mais rápido.': 'Skoči kad kazaljka prođe. Sve je brža.',
  'Ponte do riacho': 'Most preko potoka',
  'Leve as três tábuas até a ponte. Cuidado com as pedras que afundam!': 'Odnesi tri daske do mosta. Pazi na kamenje koje tone!',
  'Quem está em qual toca?': 'Tko je u kojoj jazbini?',
  'Siga os bichos de toca em toca. No fim, aponte onde está o do balão.': 'Prati životinjice od jazbine do jazbine. Na kraju pokaži gdje je ona iz oblačića.',
  'As chaves da porteira': 'Ključevi vratnica',
  'Pegue uma cenoura dourada e leve até a porteira. Falta uma: empurre quem estiver carregando!': 'Uzmi zlatnu mrkvu i odnesi je do vratnica. Jedna nedostaje: gurni onoga tko je nosi!',
  'Destampe os potes': 'Otvori staklenke',
  'Gire cada tampa para o lado da seta, depressa. O lado errado aperta de novo.': 'Okreni svaki poklopac na stranu strelice, brzo. Pogrešna strana ga opet steže.',
  'Praga na toca': 'Štetočine u jazbini',
  'Bata nas lagartas que saírem das tocas. No coelhinho, não!': 'Udaraj gusjenice koje izlaze iz rupa. Samo ne zečića!',
  'Rebater o rabanete': 'Odbij rotkvicu',
  'Rebata quando o rabanete chegar à base. Bem na hora, vai mais longe.': 'Odbij kad rotkvica stigne do baze. Točno na vrijeme — leti dalje.',
  'Regar a horta': 'Zalij povrtnjak',
  'Leve a nuvem até o canteiro com sede.': 'Odvedi oblačić do žedne gredice.',
  'Qual destes cresce debaixo da terra?': 'Što od ovoga raste pod zemljom?',
  'Quantas orelhas tem um coelho?': 'Koliko ušiju ima zec?',
  'Duas': 'Dva',
  'Três': 'Tri',
  'Quatro': 'Četiri',
