  'Minigolfe 3D': 'Minigolf 3D',
  'Oito buracos em 3D, com rampas, castelo e moinho, todos jogando o mesmo ao mesmo tempo. Arraste para mirar e dar a força, e solte. Ganha quem somar menos tacadas.': 'Osam rupa u 3D-u, s rampama, dvorcem i vjetrenjačom, svi igraju istu u isto vrijeme. Povuci za ciljanje i snagu, pa pusti. Pobjeđuje onaj s najmanje udaraca ukupno.',
  'Ver o buraco de cima': 'Pogledaj rupu odozgo',
  'Fora da pista! Mais uma tacada.': 'Izvan staze! Još jedan udarac.',
  'Arraste para o lado para mirar e para baixo para a força, e solte. No teclado: as setas miram, e o Espaço segurado dá a força.': 'Povuci ustranu za ciljanje i prema dolje za snagu, pa pusti. Na tipkovnici: strelice ciljaju, a držanje Razmaknice daje snagu.',
  'Futebol dos coelhos': 'Zečji nogomet',
  'Futebol de campo pequeno, visto de cima. Encoste na bola para conduzir, segure Espaço para chutar mais forte e passe com X. Na sala, os times se completam com robôs.': 'Nogomet na malom terenu, gledan odozgo. Dotakni loptu da je vodiš, drži Razmaknicu za jači udarac i dodaj s X. U sobi se ekipe popunjavaju robotima.',
