  'Caça às pragas da horta': 'Lov na štetočine u vrtu',
  'Corvos e gafanhotos atacam a horta. Mire e clique para acertar antes que fujam: a munição é contada, e cada onda vem mais rápida. Ganha quem fizer mais pontos.': 'Vrane i skakavci napadaju vrt. Nišani i klikni da ih pogodiš prije nego što pobjegnu: streljivo je odbrojano, a svaki val dolazi brže. Pobjeđuje onaj tko skupi najviše bodova.',
  'Mire e clique nas pragas antes que fujam. Cada tiro gasta uma cenoura.': 'Nišani i klikni na štetočine prije nego što pobjegnu. Svaki hitac troši jednu mrkvu.',
