  'Setas para correr, Espaço para pular (segure para ir mais alto).': 'Strelice za trčanje, Razmaknica za skok (drži za viši skok).',
  'Nenhum amigo jogou esta fase ainda.': 'Ovu razinu još nitko od prijatelja nije igrao.',
