  'Comprar': 'Kupi',
  '{nome} chegou à cenoura dourada.': '{nome} stiže do zlatne mrkve.',
  'Quantas rodadas?': 'Koliko rundi?',
  'Os coelhos defendem a horta de raposas, corvos e um texugo. Andem juntos, batam em combo e cuidem uns dos outros: de 1 a 4 pessoas.': 'Zečevi brane vrt od lisica, vrana i jazavca. Krećite se zajedno, udarajte u kombu i pazite jedni na druge: od 1 do 4 osobe.',
  'Pulo do coelho': 'Zečji skok',
  'Uma corrida de plataforma: correr, pular e não cair. Sozinho, contra o relógio e os fantasmas dos amigos; com a turma, ao vivo, numa fase ou nas três.': 'Utrka na platformama: trči, skači i ne padni. Solo, protiv sata i duhova prijatelja; s ekipom, uživo, na jednoj razini ili na sve tri.',
  'Troque dois legumes vizinhos para juntar três ou mais iguais. A pilha sobe sem parar: não deixe chegar ao topo. Com a turma, as cadeias e os combos mandam caixotes para os outros.': 'Zamijeni dva susjedna povrća i složi tri ili više istih. Hrpa raste bez prestanka: ne daj joj da dođe do vrha. S ekipom, lanci i kombo udarci šalju sanduke drugima.',
  'Seis buracos de minigolfe, todos jogando o mesmo ao mesmo tempo. Puxe a bola para trás e solte para dar a tacada. Ganha quem somar menos tacadas.': 'Šest rupa minigolfa, svi igraju istu u isto vrijeme. Povuci lopticu unatrag i pusti za udarac. Pobjeđuje najmanji zbroj udaraca.',
  'Cada um joga o dado na sua vez e anda pela horta. Junte cenouras para comprar a cenoura dourada, e depois de cada rodada a turma joga um microjogo. Ganha quem tiver mais cenouras douradas.': 'Kocka se baca naizmjence i ide se kroz vrt. Skupljaj mrkve da kupiš zlatnu mrkvu, a nakon svake runde ekipa igra mini-igru. Pobjeđuje najviše zlatnih mrkvi.',
