  'Ande pelas capitais do Brasil, compre cidades e cobre aluguel de quem parar nelas. Com uma região inteira, dá para construir prédios. Troque, dispute nos leilões e não fique sem dinheiro.': 'Putuj po glavnim gradovima Brazila, kupuj gradove i naplaćuj najamninu onima koji se na njima zaustave. S cijelom regijom možeš graditi zgrade. Mijenjaj, licitiraj na dražbama i ne ostani bez novca.',
