  'No app do Syden, o recorte funciona com qualquer fundo.': 'U aplikaciji Syden uklanjanje radi s bilo kojom pozadinom.',
  'O recorte com o modelo falhou, e ficou o recorte simples.': 'Uklanjanje pomoću modela nije uspjelo, pa je korišteno jednostavno.',
