  Bispo: 'Lovac',
  'Cozinha da toca': 'Kuhinja jazbine',
  'Pegue os ingredientes nos caixotes, pique na tábua, cozinhe no fogão e no forno sem queimar, monte no prato e entregue na janela. Todos recebem os mesmos pedidos: ganha quem entregar mais pratos em 3 minutos.': 'Uzmi sastojke iz sanduka, nasjeckaj ih na dasci, skuhaj na štednjaku i u pećnici da ne zagore, složi na tanjur i predaj na prozoru. Svi dobivaju iste narudžbe: pobjeđuje tko preda najviše tanjura za 3 minute.',
  'Pegar ou largar': 'Uzmi ili spusti',
  'Este jogo precisa de gráficos 3D, que não abriram neste aparelho.': 'Ova igra treba 3D grafiku, koja se nije otvorila na ovom uređaju.',
  'Este prato não é o pedido.': 'Ovaj tanjur nije narudžba.',
