  '{n}% do caminho': '{n} % puta',
  'Gincana da toca': 'Poligon s preprekama iz jazbine',
  'Uma corrida de obstáculos em 3D: corra, pule e se equilibre por plataformas, esteiras, serras e varredores até a bandeira. Caiu, volta à última bandeira. No Solo, contra o relógio e os fantasmas dos amigos.': 'Utrka s preprekama u 3D-u: trči, skači i drži ravnotežu na platformama, trakama, pilama i rotirajućim šipkama do zastave. Pad znači povratak na zadnju zastavu. U solo igri protiv sata i duhova prijatelja.',
  'Quedas: {n}': 'Padovi: {n}',
  'Tocar o sino: todos os trabalhadores para dentro do centro da vila': 'Udari zvono: svi radnici u središte sela',
