  "Registros limitados de Docker, SSH, logind e kernel dos três boots mais recentes. Podem conter endereços IP.": "Ograničeni zapisi Dockera, SSH-a, logind-a i jezgre iz posljednja tri pokretanja. Mogu sadržavati IP adrese.",
  "Atualizar diagnóstico": "Osvježi dijagnostiku",
  "Ainda não há snapshot. Ele será coletado na próxima abertura do cofre.": "Još nema snimke. Prikupit će se pri sljedećem otvaranju trezora.",
  "Coletado em {data}": "Prikupljeno {data}",
