  "Os mesmos números do painel do provedor. Inclui o disco, que o servidor não mede sozinho.": "Isti brojevi kao na upravljačkoj ploči pružatelja. Uključuje disk, koji poslužitelj sam ne mjeri.",
  "Ações no servidor": "Radnje na poslužitelju",
  "O histórico da Hetzner: ligar, desligar e reiniciar, pelo painel ou pela API. Uma queda sem ação aqui não foi comandada por esses caminhos.": "Povijest u Hetzneru: uključivanje, isključivanje i ponovno pokretanje, s ploče ili preko API-ja. Prekid bez radnje ovdje nije pokrenut tim putevima.",
  "Nenhuma ação registrada.": "Nema zabilježenih radnji.",
