  'Cada grupo tem o seu toque. Ponha alguém num grupo, ou escolha um toque só para essa pessoa, com o botão direito no nome dela.': "Svaka grupa ima svoju melodiju. Stavi nekoga u grupu ili odaberi melodiju samo za tu osobu, desnim klikom na njezino ime.",
  'Apagar grupo': "Izbriši grupu",
  'Toca quando alguém liga para você numa conversa privada, mesmo com os sons de aviso desligados. Em "Não perturbe", a ligação aparece sem tocar.': "Zvoni kad te netko nazove u privatnom razgovoru, čak i kad su zvukovi obavijesti isključeni. U „Ne ometaj“ poziv se prikaže bez zvonjenja.",
  'Avisar das ligações com o Syden em segundo plano?': "Obavještavati te o pozivima dok je Syden u pozadini?",
