  'Desfocado': "Zamuti",
  'Desfoca, apaga ou troca o que aparece atrás de você. A imagem da câmera não sai do computador para isso.': "Zamućuje, briše ili mijenja ono što se vidi iza tebe. Slika s kamere zbog toga ne napušta tvoje računalo.",
  // A transmissão personalizada (16/11/2026)
  'Nativa': "Izvorna",
  'Resolução': "Razlučivost",
  'Quadros por segundo': "Sličica u sekundi",
  'Para quando a escolha automática errar: a resolução e os quadros ficam os que você escolher, do começo ao fim da transmissão.': "Za kad automatski odabir pogriješi: razlučivost i sličice ostaju kakve odabereš, od početka do kraja prijenosa.",
  // O Syden Broadcast (16/11/2026)
  'Os efeitos de voz e de câmera feitos no seu computador, sem enviar nada a um servidor.': "Efekti za glas i kameru koji se rade na tvom računalu, bez slanja ičega na poslužitelj.",
  // O Comando Cenoura (16/11/2026)
  'Comando Cenoura': "Komandos Mrkva",
  'Correr e atirar com a turma: o lança-cenouras mira em oito direções, a granada abre caminho e quem solta os coelhinhos presos ganha reforço. O dragão espera no fim: de 1 a 4 pessoas.': "Trči i pucaj s ekipom: bacač mrkvi nišani u osam smjerova, granata otvara put, a tko oslobodi zatvorene zečiće dobiva pojačanje. Zmaj čeka na kraju: od 1 do 4 osobe.",
  'Andar e mirar': "Hodaj i nišani",
  'Granada': "Granata",
  // A Masmorra da Toca (16/11/2026)
  'Masmorra da Toca': "Tamnica jazbine",
  'Atravessem juntos a toca do rei-cogumelo: salas cheias de bichos, um baú com a cenoura que vai e volta, botões que pedem dois ao mesmo tempo e a porta trancada. De 1 a 4 pessoas.': "Prođite zajedno kroz jazbinu kralja-gljive: sobe pune stvorenja, škrinja s mrkvom koja leti tamo i natrag, gumbi koji traže dvoje odjednom i zaključana vrata. Od 1 do 4 osobe.",
  // O Ringue da Toca (16/11/2026)
  'Ringue da Toca': "Ring kod jazbine",
  'Boxe de reflexo contra três adversários do computador. Leia o aviso de cada golpe, esquive ou defenda e bata na brecha. Bater quando a luva brilha enche a estrela do soco forte.': "Boks refleksa protiv tri protivnika s računala. Čitaj najavu svakog udarca, izmakni se ili blokiraj i udari u otvor. Udarac dok rukavica sjaji puni zvijezdu jakog udarca.",
  'Esquivar': "Izmakni se",
  'Abaixar e defender': "Sagni se i blokiraj",
  'Socar': "Udari",
  'Soco forte': "Jak udarac",
  'Aperte os socos para levantar!': "Pritišći udarce da ustaneš!",
  'Lutas vencidas: {n}': "Dobivene borbe: {n}",
  'Nocaute!': "Nokaut!",
  // A Rota Estelar (16/11/2026)
  'Rota Estelar': "Zvjezdana ruta",
  'Coelhos em naves pela superfície de um planeta e pelo espaço: atire, segure o tiro para travar a mira, gire para desviar dos tiros e escolha o caminho na bifurcação. A turma voa a mesma rota, e o chefe espera no fim.': "Zečevi u svemirskim brodovima iznad površine planeta i u svemiru: pucaj, drži pucanj da zaključaš metu, okreni se da odbiješ hice i odaberi put na račvanju. Ekipa leti istom rutom, a šef čeka na kraju.",
  'Pirueta': "Okret",
  'Segure para travar a mira': "Drži za zaključavanje",
  // O Pinball da Horta (16/11/2026)
  'Pinball da Horta': "Fliper u vrtu",
  'Uma mesa de pinball na horta: segure a mola, rebata nos repolhos e derrube as três cenouras para acender a toca do coelho, que solta mais uma bola. Três bolas, e sacudir demais trava a mesa.': "Fliper stol u povrtnjaku: drži oprugu, odbijaj se od kupusa i obori tri mrkve da upališ zečju rupu, koja pušta još jednu kuglicu. Tri kuglice, a previše drmanja zaključava stol.",
  'Palhetas': "Flipovi",
