  "A armadilha de {nome} disparou: quem sai junto?": "Zamka ({nome}) je okinula: tko izlazi zajedno?",
  "A largada precisa de uma reta.": "Za start treba ravni dio.",
  "A Maravilha de {nome} ficou de pé por 2 minutos.": "Čudo ({nome}) stoji već 2 minute.",
  "A mesma posição pela terceira vez empata, e 20 lances só de dama sem comer também.": "Ista pozicija treći put znači neriješeno, kao i 20 poteza samo damama bez uzimanja.",
  "À noite, veja quem os lobisomens atacaram. Uma poção salva essa pessoa e outra tira alguém do jogo; cada uma vale uma vez.": "Noću vidi koga su vukodlaci napali. Jedan napitak spašava tu osobu, a drugi nekoga izbacuje iz igre; svaki vrijedi jednom.",
  "A partida se desencontrou entre os computadores e foi encerrada.": "Računala su izgubila usklađenost pa je partija prekinuta.",
  "A pedra que termina o lance na última fileira vira dama, que anda a diagonal inteira.": "Kamen koji završi potez u zadnjem redu postaje dama, koja ide cijelom dijagonalom.",
