  'Nenhuma conversa ainda. Toque em alguém na lista de pessoas da comunidade e escolha "Enviar mensagem".': "Još nema razgovora. Dodirni nekoga na popisu članova zajednice i odaberi „Pošalji poruku”.",
  "Varia": "Različito",
  "Vitória de {nomes}": "Pobjeda: {nomes}",
  "Vocês derrubaram os dois centros da vila da outra equipe.": "Tvoja ekipa srušila je oba središta sela druge ekipe.",
  // Os mini-games e as insígnias (19/11/2026)
  "A cidade que ninguém compra vai a leilão. Hipotecar uma cidade dá dinheiro, mas ela não cobra aluguel.": "Grad koji nitko ne kupi ide na dražbu. Založeni grad donosi novac, ali ne naplaćuje najamninu.",
  "A dica acende a peça que move. O problema com dica não pontua; na corrida, ela tira 10 segundos.": "Pomoć osvijetli figuru koja se treba pomaknuti. Zadatak s pomoći ne donosi bodove, a u utrci pomoć oduzima 10 sekundi.",
  "A manilha é o valor seguinte ao da vira e ganha de todas. Entre elas: ouros, espadas, copas e paus, o zap.": "Adut je sljedeća vrijednost nakon okrenute karte i pobjeđuje sve ostale. Među njima: karo, pik, herc i tref — zap.",
  "A última nave de cada volta sai.": "Posljednji brod u svakom krugu ispada.",
  "Abaixar": "Sagni se",
  "Acertos em sequência: {n}": "Riješeno zaredom: {n}",
  "Ande pelo dado e compre a capital onde parar. Quem para na cidade de outro paga aluguel.": "Idi po kocki i kupi prijestolnicu gdje staneš. Tko stane na tuđi grad, plaća najamninu.",
  "Cada linha, coluna e bloco de 3 × 3 tem os números de 1 a 9, sem repetir.": "Svaki redak, stupac i blok 3 × 3 ima brojeve od 1 do 9, bez ponavljanja.",
  "Cada um recebe 3 cartas. Leva a mão quem ganhar 2 das 3 rodadas.": "Svatko dobiva 3 karte. Ruku nosi tko dobije 2 od 3 runde.",
  "Campeonato": "Prvenstvo",
  "Com 11 pontos, a dupla vê as cartas e decide se joga a mão de onze. Vence quem chegar a 12.": "S 11 bodova par gleda karte i odlučuje igra li ruku jedanaest. Pobjeđuje tko dođe do 12.",
  "Com a região inteira, construa até 4 prédios: o aluguel sobe a cada um.": "S cijelom regijom gradi do 4 zgrade: najamnina raste sa svakom.",
  "Com estrelas, o soco forte (★) gasta todas de uma vez e dói mais.": "Jak udarac (★) troši sve zvijezde odjednom i više boli.",
  "Dica": "Pomoć",
  "Dica: este problema não pontua": "Pomoć: ovaj zadatak ne donosi bodove",
  "Dica: tira 10 segundos": "Pomoć: minus 10 sekundi",
  "Eliminação": "Eliminacija",
  "Encoste uma pedra numa ponta da mesa com o mesmo número.": "Prisloni pločicu na kraj stola s istim brojem.",
  "Escolha a casa e depois o número. O lápis anota só para você.": "Odaberi polje, pa broj. Bilješke olovkom vidiš samo ti.",
  "Esquive do golpe e soque logo depois: é o contra-ataque, e vale estrela.": "Izmakni se udarcu i odmah udari: to je protunapad i donosi zvijezdu.",
  "Fora da corrida na volta {n}.": "Izvan utrke u krugu {n}.",
  "Força das cartas": "Jačina karata",
  "Ganha o maior patrimônio no fim das rodadas, ou quem sobrar.": "Pobjeđuje najveća imovina na kraju rundi, ili tko posljednji ostane.",
  "Iniciante": "Početnik",
  "Mestre": "Majstor",
  "Na sequência, cada acerto traz um problema mais difícil, e o primeiro erro acaba.": "U nizu svaki pogodak donosi teži zadatak, a prva pogreška ga završava.",
  "O número pequeno no botão diz quantos ainda faltam.": "Mali broj na gumbu pokazuje koliko ih još nedostaje.",
  "Os cinco traçados seguidos contra o computador, com pontos.": "Pet staza zaredom protiv računala, s bodovima.",
  "Peça truco e a mão vale 3. Quem responde aceita, corre ou aumenta para 6, 9 ou 12.": "Zovi truco i ruka vrijedi 3. Tko odgovara prihvaća, bježi ili diže na 6, 9 ili 12.",
  "Quem bate fica sem pedras e leva os pontos das mãos dos outros. Trancado, leva quem tem menos pontos na mão.": "Tko izađe ostaje bez pločica i uzima bodove iz ruku ostalih. Kad je igra blokirana, uzima onaj s najmanje bodova u ruci.",
  "Sem pedra que sirva, compre. Sem nada para comprar, a vez passa.": "Bez pločice koja odgovara, vuci. Kad nema što vući, red prelazi dalje.",
  "Sequência": "Niz",
  "Soque quando a luva brilhar: o golpe para e você ganha uma estrela.": "Udari kad rukavica zasja: udarac staje i dobivaš zvijezdu.",
  "Treino livre": "Slobodni trening",
