  "Saara": "Sahara",
  "Sai um animal secreto, e cada um chuta outros. Cada chute mostra o que bate com o secreto: a classe, a dieta, onde ele vive e o peso. Quem acertar com menos chutes ganha mais pontos.": "Izvuče se tajna životinja, a svatko pogađa druge. Svaki pokušaj pokaže što se poklapa s tajnom: razred, prehrana, gdje živi i težina. Tko pogodi s manje pokušaja, dobiva više bodova.",
  "Sai um dinossauro secreto, e cada um chuta outros. Cada chute mostra o que bate com o secreto: o período, a dieta, o grupo, o comprimento e onde ele foi achado. Quem acertar com menos chutes ganha mais pontos.": "Izvuče se tajni dinosaur, a svatko pogađa druge. Svaki pokušaj pokaže što se poklapa s tajnim: razdoblje, prehrana, skupina, duljina i gdje je pronađen. Tko pogodi s manje pokušaja, dobiva više bodova.",
  "Sai um elemento químico secreto, e cada um chuta outros. Cada chute mostra o que bate com o secreto: a família, o estado físico, o período, o grupo e o número atômico. Quem acertar com menos chutes ganha mais pontos.": "Izvuče se tajni kemijski element, a svatko pogađa druge. Svaki pokušaj pokaže što se poklapa s tajnim: obitelj, agregatno stanje, period, skupina i atomski broj. Tko pogodi s manje pokušaja, dobiva više bodova.",
  "Sai um estado secreto do Brasil, e cada um chuta outros. Cada chute mostra a distância e a direção até o secreto, a região, a população, a área, o litoral e a fronteira com outro país. Quem acertar com menos chutes ganha mais pontos.": "Izvuče se tajna savezna država Brazila, a svatko pogađa druge. Svaki pokušaj pokaže udaljenost i smjer do tajne, regiju, stanovništvo, površinu, obalu i granicu s drugom zemljom. Tko pogodi s manje pokušaja, dobiva više bodova.",
